if(_transaction_id <> "-1")

{
	logtime("Naveen**ComAttrs**Inside",0);
	results = bmql("SELECT $selectClause FROM commerce.transaction");
	// moved this commented logic from all product family level to flexOneView model as part of CPQ_Q2C-231
        //Jira Ticket :CPQ_Q2C-61 - Start
