        //Jira Ticket :CPQ_Q2C-61 - End

}elif(find(commerceAttrs,"customerNumber_t")<>-1){
	//print "in first elif";
	if(occUser)
	{
	custNum="";
	priceBook ="";
	salesChannel ="";
	mainStrAry = split(commerceAttrs,"*:2:*");
	for i in mainStrAry{
		subStrAry = split(i,"*:1:*");
