		val = subStrAry[1];

		if(key == "customerNumber_t"){
			custNum= val;
		}
		put(occCommDict,key,val);
		}
		//print custNum;
	header_rs = bmql("SELECT NAME, PRICE_LIST_NAME, FOB_POINT, FREIGHT_TERM, SHIP_COMPLETE, SALES_OFFICE, SALES_CHANNEL_CODE FROM Customer_Header WHERE CUSTOMER_STATUS='A' AND ACCOUNT_NUMBER=$custNum");
	for hdr in header_rs{
		priceBook = get(hdr, "PRICE_LIST_NAME");
		salesOffice = get(hdr, "SALES_OFFICE");
		salesChannel = get(hdr, "SALES_CHANNEL_CODE"); 
	}
	put(occCommDict,"salesChannel_t",salesChannel);
	put(occCommDict,"priceBook_t",priceBook);
	occCommKeys = keys(occCommDict);
	for key in occCommKeys 
	{
		retString=retString + key + CONFIG_DELIM1 + get(occCommDict,key) + CONFIG_DELIM2;
	}


	if(ENDSWITH(retString,CONFIG_DELIM2))
	{
		retString=substring(retString,0,len(retString)-len(CONFIG_DELIM2));
	}
	return retString;
	}
	return commerceAttrs;
}elif(commerceAttrs<>""){
	//print "in second elif";
	/* Parsing input */
	mainStrAry = split(commerceAttrs,"*:2:*");
	for i in mainStrAry{
		subStrAry = split(i,"*:1:*");
		key = subStrAry[0];
		val = subStrAry[1];
		if(key=="customerNumber"){
		        /*if(val=="" OR val=="null" OR val=="undefined"){
		         val = "GUEST";
		        }*/
			customerNumber = val;
			key = "customerNumber_t";
		}elif(key=="shipToState"){
			shipToState = val;
			key = "shipToState";
		}elif(key=="shipToCountry"){
			shipToCountry = val;
			key = "configUDCC_t";
		}elif(key=="operatingUnit"){
			operatingUnit = val;
			key = "operatingUnit_t";
		}elif(key=="currency"){
			currency = val;
			key = "currency_t";
		}
		//Sowmya K Added for CPQM 1811 - START
		elif(key=="shipToStateProv"){
			shipToStateProv = val;
			key = "_ship_to_state";
		}
		//Sowmya K Added for CPQM 1811 - END
		//CPQM 2495 - START
		elif(key=="industryVerticalSFDC"){
			industryVerticalSFDC = val;
			key = "industryVerticalSFDC_t";
		}
		//Sowmya K Added for CPQM 1852 - START
		elif(key=="fTECount"){
			fTECount = val;
			key = "fTECnt_t";
		}
		elif(key=="proportionalFTECount"){
			proportionalFTECount = val;
			key = "proportionalFTECnt_t";
		}
		//Sowmya K Added for CPQM 1852 - END
		elif(key=="punchInSource"){
			punchInSource = val;
			key = "punchInSource_t";
		}

		elif(key=="salesforceGDriveFolderLink"){
			salesforceGDriveFolderLink = val;
			key = "salesforceGDriveFolderLink_t";
		}
		put(commerceAttrsData,key,val);
	}
	put(commerceAttrsData,"ultimateDestinationCountryCode_t",shipToCountry);
	put(commerceAttrsData,"_ship_to_state",shipToStateProv); // Sowmya K:Added for CPQM 1811
	//Sowmya K Added for CPQM 1852 - START
	put(commerceAttrsData,"fTECnt_t",fTECount);
	put(commerceAttrsData,"proportionalFTECnt_t",proportionalFTECount);
	put(commerceAttrsData,"punchInSource_t",punchInSource);
	put(commerceAttrsData,"salesforceGDriveFolderLink_t",salesforceGDriveFolderLink);
	//Sowmya K Added for CPQM 1852 - END
	/* Customer Header Data */
	header_rs = bmql("SELECT NAME, PRICE_LIST_NAME, FOB_POINT, FREIGHT_TERM, SHIP_COMPLETE, SALES_OFFICE, SALES_CHANNEL_CODE FROM Customer_Header WHERE CUSTOMER_STATUS='A' AND ACCOUNT_NUMBER=$customerNumber");
	for hdr in header_rs{
		priceBook = get(hdr, "PRICE_LIST_NAME");
		salesOffice = get(hdr, "SALES_OFFICE");
		salesChannel = get(hdr, "SALES_CHANNEL_CODE");
		put(commerceAttrsData,"salesChannel_t",salesChannel);
		put(commerceAttrsData,"priceBook_t",priceBook);
	}

	/* Find validation org */
	valOrgRs = bmql("SELECT ValidationOrg FROM OUMapping WHERE OperatingUnit=$operatingUnit");
	for result in valOrgRs{
		validationOrg = get(result,"ValidationOrg");
		put(commerceAttrsData,"validationOrg_t",validationOrg);
	}

	inputdata =dict("string");
	put(inputdata,"CUSTOMER_NUMBER",customerNumber);
	put(inputdata,"SALES_CHANNEL",salesChannel);
	put(inputdata,"SALES_OFFICE",salesOffice);
	put(inputdata,"SHIP_TO_STATE",shipToState);
	put(inputdata,"SHIP_TO_COUNTRY",shipToCountry);

	overRidePriceBook = util.getPriceBookOverride(inputdata);
	if (overRidePriceBook<>""){
		priceBook = overRidePriceBook;
		put(commerceAttrsData,"priceBook_t",priceBook);
	}
}



for result in results
{
	for attr in commerceAttrsAry
	{
		put(commerceAttrsData,attr,get(result,attr));
	}
}

if(commerceAttrOverride <> "")
{
	CONFIG_DELIM2Array=split(commerceAttrOverride, CONFIG_DELIM2);
	for CONFIG_DELIM2Element in CONFIG_DELIM2Array
	{
		CONFIG_DELIM1Array=split(CONFIG_DELIM2Element, CONFIG_DELIM1);
		put(commerceAttrsData,CONFIG_DELIM1Array[0],CONFIG_DELIM1Array[1]);
	}
}
// 11/03/2021 IT_APX_APXNEXT-160: Start. Suraj: adding below code to set sales channel for punchout
if(containsKey(commerceAttrsData,"salesChannel_t") AND get(commerceAttrsData,"salesChannel_t") == "" AND get(commerceAttrsData,"configAction_t") == "Punch-out")
{
	customerNumber = get(commerceAttrsData,"customerNumber_t");
	salesChannel_rs = bmql("SELECT SALES_CHANNEL_CODE FROM Customer_Header WHERE CUSTOMER_STATUS='A' AND ACCOUNT_NUMBER=$customerNumber");
	salesChannel = "";
	for result in salesChannel_rs{
		salesChannel = get(result,"SALES_CHANNEL_CODE");
	}
	put(commerceAttrsData,"salesChannel_t",salesChannel);
}
//IT_APX_APXNEXT-160: End
commerceAttrskeys=keys(commerceAttrsData);
sort(commerceAttrskeys);//CPQM-5402
for key in commerceAttrskeys
{
	//CPQM-5402 Start
	//retString=retString + key + CONFIG_DELIM1 + get(commerceAttrsData,key) + CONFIG_DELIM2;//Existing
	eachKey = key;
	//If condition: allow to add only if the keys have values among these 3 attributes
	if((eachKey == "priceDateChange_t") OR (eachKey =="priceDate_t") OR (eachKey=="freezePriceDate_c")){
		if(get(commerceAttrsData,eachKey) <> "" AND NOT isnull(get(commerceAttrsData,eachKey))){
			retString=retString + eachKey + CONFIG_DELIM1 + get(commerceAttrsData,eachKey) + CONFIG_DELIM2;
		}
	}
	else{
	retString=retString + eachKey + CONFIG_DELIM1 + get(commerceAttrsData,eachKey) + CONFIG_DELIM2;
	}
	//CPQM-5402 End	

}


if(ENDSWITH(retString,CONFIG_DELIM2))
{
	retString=substring(retString,0,len(retString)-len(CONFIG_DELIM2));
}

if(get(commerceAttrsData,"punchInSource_t") == "OCC"){

	return commerceAttrs;
}

t2 = getcurrenttimeinmillis();
logtime("commerceAttr exe:", t2-t1);
return retString;

retVal = false;
reconfiguredFlag = false;
conversionflag = false;
results = bmql("SELECT sm_reconfiguredFlag_t,sm_convertedQuote_t FROM commerce.transaction");

for each in results{
	if(get(each, "sm_reconfiguredFlag_t") == "true"){
		reconfiguredFlag = true;		
	}
	// Added sMP3_1_CONFIG_FLAG condition by Hashwitha for SMP3.1 Release
	if(get(each, "sm_convertedQuote_t") == "true" AND sMP3_1_CONFIG_FLAG == false){
		conversionflag = true;		
	}
}
//Added conversion flag to fire this rule during conversion process
if(commerceAttrs == "" OR _system_config_document_number <> -1 OR find(_BM_USER_GROUPS, "OCC User") <> -1 OR reconfiguredFlag  OR conversionflag){
	retVal = true;
}

return retVal;

/**
