{
	splitEachRecord = split(eachRecord,recSep);
	if(findinarray(splitEachRecord,"productSelectionProduct_all") <> -1)
	{
		requiredFlag = requiredFlag + "|^|" + splitEachRecord[1];
	}
}


return requiredFlag;

CONSTANTS =util.constants();
commerceDelim1=get(CONSTANTS,"COMMERCE_DELIM1");
