CONFIG_DELIM2=get(CONSTANTS,"CONFIG_DELIM2");
results =recordset();
commerceAttrsData = dict("string");
//commerce attribute variable names. Every new attribute whose value is needed should be added to this array
commerceAttrs = string[]{"nonMandatoryItems_t","transactionID_t","transactionName_t","owner_t","customerNumber_t","salesChannel_t","configUDCC_t","system_supplier_company_name_t","ultimateDestinationCountryCode_t","currentCounterForNonMandatoryParts_t","configAction_t","cpqModelClasssification_t"};
selectClause=join(commerceAttrs,", ");

if(_transaction_id <> "-1")
{
results = bmql("SELECT $selectClause FROM commerce.transaction");

}

for result in results
{
	for attr in commerceAttrs 
	{
