   selModel = _bm_model_variable_name;

if(relatedServicesType_apcr==""){
eval = false;
}

//Fetching rows based on model and related service type selection
DataTableRecordsSets = bmql("SELECT DISTINCT M.ConfigAttrValue FROM Oracle_BomItemMap M INNER JOIN Oracle_BomItemDef D ON D.VariableName = M.BomItemVarName WHERE D.RootVariableName=$selModel AND M.ItemType = 'Related Services' AND M.ItemCategory IN $ServType");

  for data in DataTableRecordsSets{
  if(get(data,"ConfigAttrValue")<>""){
     returnVal = returnVal + get(data,"ConfigAttrValue") + "|^|";
     }
     }
return returnVal;

quoteJson = json();
if(quoteInformation<>""){
  quoteJson = json(quoteInformation);
}

retVal = jsonget(quoteJson,"QUOTENUMBER");

if(not isnull(retVal)){
  return retVal;
}else{
  return "";
}

