			put(isSelectedDict,tempValHolderStrAry[0],atoi(tempValHolderStrAry[3]));
			put(posDict,tempValHolderStrAry[0],pos);
		}
	} 
	if(not(isempty(keys(isSelectedDict))))
	{
		valFlag = 1;
		valuesKeys = keys(isSelectedDict);
		for cnt in loop{
			if(findinarray(valuesKeys,solutionCategoryParts_apcr[cnt])<>-1){
				val = get(isSelectedDict,solutionCategoryParts_apcr[cnt]);
				append(returnVal,val);
			}
			else
			{
				//FSNACOF-1946 - NK: Solution Category isn't passing in the ROL Payload
				if(ISNULL(solutionCategory_apcr[cnt]) OR solutionCategory_apcr[cnt] == "") {
					if(findinarray(valuesKeys,solutionCategoryParts_apcr[cnt])<>-1){
						val = get(isSelectedDict,solutionCategoryParts_apcr[cnt]);
						append(returnVal,val);
					}
				}else{
					append(returnVal,0);
				}
			}			
		}
	}

	if(valFlag > 0){
	 return returnVal;
	}
	else{
	return solutionCategoryQuantity_apcr;
	}
}

