CONFIG_DELIM1 = get(util.constants(),"CONFIG_DELIM1");
CONFIG_DELIM2 = get(util.constants(),"CONFIG_DELIM2");

recSep = "@@@";
rowSep = "$$$";

cpqModel = upper(_bm_model_variable_name);

// One query, gets all possible related service items
allRecs = bmql("SELECT D.PartNumber, M.ItemCategory, M.ConfigAttrValue, M.ConfigAttrValue2 FROM Oracle_BomItemMap M INNER JOIN Oracle_BomItemDef D ON D.VariableName = M.BomItemVarName WHERE D.RootVariableName=$cpqModel AND M.ItemType = 'Related Services'");

// Prepare record arrays
PartAry = string[];
ServiceCatAry = string[];
ServiceTypeAry = string[];
DescAry = string[];

for rec in allRecs {
    append(PartAry, get(rec, "PartNumber"));
    append(ServiceCatAry, get(rec, "ConfigAttrValue"));
    append(ServiceTypeAry, get(rec, "ItemCategory"));
    append(DescAry, get(rec, "ConfigAttrValue2"));
}

// Optional filters
typeSolutionSet = string[];
catSolutionSet  = string[];

if(relatedServicesType_apcr <> "") { 
    typeSolutionSet = split(relatedServicesType_apcr, "~");
}
if(relatedServiceCategory_apcr <> "") {
    catSolutionSet = split(relatedServiceCategory_apcr, "~");
}

filteredReturn = "";
cnt = 0;

// Apply only active filters: type, category, both, or none
for data in PartAry {
    partNumber  = PartAry[cnt];
    serviceCat  = ServiceCatAry[cnt];
    serviceType = ServiceTypeAry[cnt];
    desc        = DescAry[cnt];

    typePass = (sizeofarray(typeSolutionSet) == 0 or findinarray(typeSolutionSet, serviceType) <> -1);
    catPass  = (sizeofarray(catSolutionSet) == 0 or findinarray(catSolutionSet, serviceCat) <> -1);

    if(typePass and catPass) {
        filteredReturn = filteredReturn + serviceCat + recSep 
        + partNumber + recSep 
        + desc + recSep 
            + serviceType + rowSep;
    }
    cnt = cnt + 1;
}

// Always provide unfiltered as well
cnt = 0;
unfilteredReturn = "";
for data in PartAry {
    partNumber  = PartAry[cnt];
    serviceCat  = ServiceCatAry[cnt];
    serviceType = ServiceTypeAry[cnt];
    desc        = DescAry[cnt];

    unfilteredReturn = unfilteredReturn + serviceCat + recSep 
        + partNumber + recSep 
        + desc + recSep 
        + serviceType +rowSep;
    cnt = cnt + 1;
}
if(NOT ISNULL(filteredReturn)){
return filteredReturn;
}
// Return both, as per your model
return unfilteredReturn;

