if((findinarray(inboxAccessoryOptionTypeMsl,"EARPIECE: 2-WIRE SURVEILLANCE KIT BLACK"))<>-1 AND (findinarray(inboxAccessoryOptionTypeMsl,"MICROPHONE: IMPRES WINDPORTING RSM"))<>-1 AND (findinarray(inboxAccessoryOptionTypeMsl,"EARPIECE: 2-WIRE SURVEILLANCE KIT BEIGE"))<>-1)
{    
    ret1 = ret1 + "|^|" + "LARGE MODEL BOX" + "|^|";
}
if((findinarray(inboxAccessoryOptionTypeMsl,"MICROPHONE: IMPRES NOISE-CANCELLING RSM"))<>-1 AND (findinarray(inboxAccessoryOptionTypeMsl,"EARPIECE: 2-WIRE SURVEILLANCE KIT BLACK"))<>-1 AND (findinarray(inboxAccessoryOptionTypeMsl,"EARPIECE: 2-WIRE SURVEILLANCE KIT BEIGE"))<>-1)
{    
    ret1 = ret1 + "|^|" + "LARGE MODEL BOX" + "|^|";
}

//when all in-box options selected
if(((findinarray(inboxAccessoryOptionTypeMsl,"MICROPHONE: IMPRES NOISE-CANCELLING RSM"))<>-1) AND ((findinarray(inboxAccessoryOptionTypeMsl,"MICROPHONE: IMPRES WINDPORTING RSM"))<>-1) AND ((findinarray(inboxAccessoryOptionTypeMsl,"EARPIECE: 2-WIRE SURVEILLANCE KIT BLACK"))<>-1) AND ((findinarray(inboxAccessoryOptionTypeMsl,"EARPIECE: 2-WIRE SURVEILLANCE KIT BEIGE"))<>-1))
{    
    ret1 = ret1 + "|^|" + "LARGE MODEL BOX" + "|^|" + "BULK" + "|^|";
}

//when no in-box options selected
if(((findinarray(inboxAccessoryOptionTypeMsl,"MICROPHONE: IMPRES NOISE-CANCELLING RSM"))==-1) AND ((findinarray(inboxAccessoryOptionTypeMsl,"MICROPHONE: IMPRES WINDPORTING RSM"))==-1) AND ((findinarray(inboxAccessoryOptionTypeMsl,"EARPIECE: 2-WIRE SURVEILLANCE KIT BLACK"))==-1) AND ((findinarray(inboxAccessoryOptionTypeMsl,"EARPIECE: 2-WIRE SURVEILLANCE KIT BEIGE"))==-1))
{    
    ret1 = ret1 + "|^|" + "STANDARD MEDIUM MODEL BOX" + "|^|" + "BULK" + "|^|";
}
return ret1;
/*
MICROPHONE: IMPRES NOISE-CANCELLING RSM
MICROPHONE: IMPRES WINDPORTING RSM
EARPIECE: 2-WIRE SURVEILLANCE KIT BLACK
EARPIECE: 2-WIRE SURVEILLANCE KIT BEIGE
*/

