retValJson = json();
customerNumber = "";

if(commerceAttrs=="" OR _transaction_id<>"-1"){
	return "";
}

/* Parsing input */
mainStrAry = split(commerceAttrs,"*:2:*");
for i in mainStrAry{
	subStrAry = split(i,"*:1:*");
	jsonput(retValJson,subStrAry[0],subStrAry[1]);
	if(subStrAry[0]=="customerNumber_t"){
	  customerNumber = subStrAry[1];
	}
}
//SMP Rel3 - to handle currency issue during modify flow from OCC of subscription origniated from CPQ direct flow

if(occ_action_type=="MODIFY" and find(commerceAttrs, "currency_t")==-1 ){
	 	 jsonput(retValJson,"currency_t", _bm_user_currency );
}

jsonput(retValJson,"PRODUCT_FAMILY","PCRBUSINESSLIGHTDEVICES");
jsonput(retValJson,"PRODUCT_LINE",upper(_bm_pline_variable_name));
jsonput(retValJson,"CPQ_MODEL",upper(_bm_model_variable_name));

jsonput(retValJson,"SUFFIX","apcr");

header_rs = bmql("SELECT NAME, PRICE_LIST_NAME, FOB_POINT, FREIGHT_TERM, SHIP_COMPLETE, SALES_OFFICE, SALES_CHANNEL_CODE FROM Customer_Header WHERE CUSTOMER_STATUS='A' AND ACCOUNT_NUMBER=$customerNumber");
for hdr in header_rs{
	priceBook = get(hdr, "PRICE_LIST_NAME");
	salesOffice = get(hdr, "SALES_OFFICE");
	salesChannel = get(hdr, "SALES_CHANNEL_CODE");
	jsonput(retValJson,"salesChannel_t",salesChannel);
	jsonput(retValJson,"priceBook_t",priceBook);
}

jsonput(retValJson,"CPQ_HOST_NAME",_BM_USER_COMPANY);
jsonput(retValJson,"CPQ_URL",util.getCPQUrl(dict("string")));

/* Fetch OCC end point */
interfaceDet = bmql("select endpoint from InterfaceDetails where interface='OCC_INSTANCE_URL' AND instance=$_BM_USER_COMPANY");
for urlRec in interfaceDet{
  jsonput(retValJson,"OCC_INSTANCE_URL",get(urlRec,"endpoint"));
  break;
}

return jsontostr(retValJson);

